INSERT INTO public.semillero_lineas (semillero_id, linea_id) VALUES ((p_datos->>'semillero_id')::integer, (p_datos->>'linea_id')::integer) RETURNING * INTO v_row;
RETURN to_jsonb(v_row);
END; $$;
CREATE OR REPLACE FUNCTION public.sp_eliminar_v2_semillero_lineas(p_izquierda integer, p_derecha integer) RETURNS boolean LANGUAGE plpgsql AS $$
BEGIN
DELETE FROM public.semillero_lineas WHERE semillero_id=p_izquierda AND linea_id=p_derecha;
RETURN FOUND;
END; $$;

